changeSet.sql:
CREATE TABLE edges (
    id              UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    from_node_id    UUID NOT NULL REFERENCES nodes(id) ON DELETE CASCADE,
    to_node_id      UUID NOT NULL REFERENCES nodes(id) ON DELETE CASCADE,
    edge_type       TEXT NOT NULL
                    CHECK (edge_type IN ('SUPPORTS','REFUTES','QUALIFIES','INVALIDATES','RESPONDS_TO')),
    rationale       TEXT,
    created_by      UUID NOT NULL REFERENCES users(id),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_edges_from_node_id ON edges(from_node_id);
CREATE INDEX idx_edges_to_node_id   ON edges(to_node_id);
CREATE INDEX idx_edges_edge_type    ON edges(edge_type);
CREATE INDEX idx_edges_created_by   ON edges(created_by);
